+function unwrapOptionState(state: unknown): unknown {
+  if (Array.isArray(state) && state.length === 1) return unwrapOptionState(state[0]);
+  if (isDependencySourceState(state)) return unwrapOptionState(state.result);
+  if (state !== null && typeof state === "object" && "success" in state) {
+    const result = state as { readonly success: unknown; readonly value?: unknown };
+    return result.success ? result.value : undefined;
+  }
+  return state;
+}
+
+function evaluateOptionDependency(
+  dependency: OptionDependencies,
+  state: Record<string | symbol, unknown>,
+  keyByOptionName: ReadonlyMap<string, string | symbol>,
+): boolean {
+  const evaluate = (condition: { readonly option: string; readonly value?: unknown }): boolean => {
+    const key = Object.prototype.hasOwnProperty.call(state, condition.option)
+      ? condition.option
+      : keyByOptionName.get(condition.option);
+    if (key === undefined || !Object.prototype.hasOwnProperty.call(state, key)) {
+      return false;
+    }
+    const value = unwrapOptionState(state[key]);
+    return Object.prototype.hasOwnProperty.call(condition, "value")
+      ? value === condition.value
+      : Boolean(value);
+  };
+  if ("option" in dependency) return evaluate(dependency);
+  const allOf = dependency.allOf;
+  const anyOf = dependency.anyOf;
+  return (allOf === undefined || allOf.every(evaluate)) &&
